select energy_manager.load_cards($cards$[
{"id":"p2-028","paper":2,"topic":"Boilers","kind":"fact","front":"What is a thermic fluid heater used for?","back":"To heat a thermal (mineral or synthetic) oil that circulates in a closed loop to deliver high-temperature process heat at low pressure.","explain":"Thermic fluid gives process temperatures around 250–300 °C without the high pressures that steam would need at those temperatures, so it suits dryers, presses and reactors. The heater itself is a fired coil heater, not a steam generator.","flash":false,"source":"BEE 2025 P2 Q14","order":2027},
{"id":"p2-029","paper":2,"topic":"Boilers","kind":"problem","front":"A coal-fired boiler generates 12 t/h of dry saturated steam with enthalpy 665 kcal/kg. Feed water is at 60 °C. Coal consumption is 2.4 t/h with GCV 4,200 kcal/kg. Find (a) the evaporation ratio and (b) the boiler efficiency by the direct method.","back":"(a) Evaporation ratio = 5.0 kg steam/kg coal; (b) Direct efficiency ≈ 72.0%","explain":"Evaporation ratio is simply steam/fuel on a mass basis. Direct efficiency compares the heat added to water/steam with the heat in the fuel. Feed water enthalpy in kcal/kg is approximately equal to its temperature in °C (Cp ≈ 1). If the steam is actually wet, the true output is lower and the direct method overstates efficiency.","steps":[{"prompt":"Calculate the evaporation ratio.","answer":"ER = 12,000 / 2,400 = 5.0 kg steam/kg coal","explain":"Evaporation ratio = kg steam generated per kg fuel."},{"prompt":"Calculate the heat output to steam.","answer":"Q_out = 12,000 × (665 − 60) = 7,260,000 kcal/h","explain":"Feed water enthalpy ≈ 60 kcal/kg (1 kcal/kg°C × 60 °C, from 0 °C reference)."},{"prompt":"Calculate the heat input from fuel.","answer":"Q_in = 2,400 × 4,200 = 10,080,000 kcal/h","explain":"Fuel flow × GCV."},{"prompt":"Compute direct efficiency.","answer":"η = 7,260,000 / 10,080,000 × 100 = 72.0%","explain":"η = useful output / input."}],"flash":false,"source":"Based on BEE 2024 P2 L3; BEE 2025 P2 S4","order":2028},
{"id":"p2-030","paper":2,"topic":"Boilers","kind":"problem","front":"An oil-fired boiler burns fuel with ultimate analysis C 84%, H 12%, S 3%, O 1% (moisture nil) and GCV 10,200 kcal/kg. Flue gas O₂ is 3% (dry) and flue gas leaves at 220 °C; ambient is 30 °C. Take Cp of dry flue gas 0.23 kcal/kg°C, Cp of superheated vapour 0.45 kcal/kg°C, latent heat 584 kcal/kg, and radiation + unaccounted losses 1.5%. Estimate boiler efficiency by the indirect method.","back":"Dry flue gas loss ≈ 6.96%, H₂ loss ≈ 7.09%, efficiency ≈ 84.4%","explain":"The indirect method subtracts each loss from 100. Dry flue gas mass is built up from CO₂, SO₂, N₂ and excess O₂ per kg fuel. The hydrogen loss is large for oil because every kg of H forms 9 kg of water that leaves as vapour carrying latent heat – this is the GCV−NCV gap and cannot be recovered without condensing the flue gas.","steps":[{"prompt":"Find theoretical air.","answer":"[2.67×0.84 + 8×0.12 + 0.03 − 0.01]/0.23 = 14.00 kg/kg fuel","explain":"Oxygen demand / 0.23."},{"prompt":"Find excess air and actual air.","answer":"EA = 3/(21−3) = 16.7%; AAS = 14.00 × 1.167 = 16.33 kg/kg","explain":"EA = O₂/(21 − O₂)."},{"prompt":"Find mass of dry flue gas per kg fuel.","answer":"CO₂ 3.08 + SO₂ 0.06 + N₂ 12.58 + excess O₂ 0.54 = 16.25 kg/kg","explain":"CO₂ = 44/12 × C; SO₂ = 2 × S; N₂ = 0.77 × AAS; O₂ = 0.23 × (AAS − theoretical air)."},{"prompt":"Dry flue gas loss.","answer":"L1 = 16.25 × 0.23 × (220 − 30) / 10,200 × 100 = 6.96%","explain":"m × Cp × (Tf − Ta) / GCV."},{"prompt":"Loss due to hydrogen in fuel.","answer":"L2 = 9 × 0.12 × [584 + 0.45 × 190] / 10,200 × 100 = 7.09%","explain":"Each kg H gives 9 kg water vapour carrying latent + superheat."},{"prompt":"Efficiency.","answer":"η = 100 − 6.96 − 7.09 − 1.5 = 84.4%","explain":"Indirect efficiency = 100 − Σ losses."}],"flash":false,"source":"syllabus","order":2029},
{"id":"p2-031","paper":2,"topic":"Boiler water","kind":"fact","front":"What is boiler blowdown and why is it necessary?","back":"Periodic or continuous removal of some boiler water to keep dissolved and suspended solids (TDS) within permissible limits.","explain":"As water evaporates the solids stay behind and concentrate. Too high TDS causes foaming, carry-over, scale and corrosion; too much blowdown wastes heat and treated water. Continuous blowdown at controlled rate with heat recovery is more efficient than heavy intermittent blowdown.","flash":false,"source":"BEE 2024 P2 L3","order":2030},
{"id":"p2-032","paper":2,"topic":"Boiler water","kind":"fact","front":"Write the formula for blowdown percentage.","back":"Blowdown % = (Feed water TDS × 100) / (Maximum permissible TDS in boiler water − Feed water TDS).","explain":"Feed water TDS is the TDS of the mixed feed (condensate + make-up). If only make-up TDS is given, multiply it by the make-up fraction to get feed TDS. Lower feed TDS (better pre-treatment or more condensate return) directly reduces blowdown and its heat loss.","flash":false,"source":"BEE 2025 P2 L2(a)","order":2031},
{"id":"p2-033","paper":2,"topic":"Boiler water","kind":"fact","front":"What is the purpose of a deaerator?","back":"To remove dissolved gases – mainly oxygen and carbon dioxide – from boiler feed water by heating it with steam.","explain":"Dissolved O₂ and CO₂ cause pitting and acidic corrosion in boilers and condensate lines. The deaerator is a direct-contact heater where steam mixes with water. Residual oxygen is then removed chemically with scavengers such as sodium sulphite or hydrazine.","flash":true,"source":"BEE 2024 P2 Q16, Q44; BEE 2025 P2 Q24, L3","order":2032},
{"id":"p2-034","paper":2,"topic":"Boiler water","kind":"fact","front":"Give an example of internal water treatment in boilers and of external treatment.","back":"Internal: chemical dosing inside the boiler such as sodium phosphate. External: softening/ion exchange, demineralisation, reverse osmosis, deaeration, clarification.","explain":"Internal treatment conditions impurities that enter the boiler so they form a removable sludge rather than hard scale. External treatment removes impurities before the water reaches the boiler and is preferred when feed water hardness/TDS is high.","flash":false,"source":"BEE 2025 P2 Q39","order":2033},
{"id":"p2-035","paper":2,"topic":"Boiler water","kind":"fact","front":"What is reverse osmosis (RO) used for in boiler feed water treatment?","back":"To remove dissolved salts (TDS) and other impurities by forcing water through a semi-permeable membrane.","explain":"RO greatly lowers feed water TDS, which reduces the required blowdown and its heat loss. Softening alone only exchanges hardness ions and does not reduce TDS.","flash":false,"source":"BEE 2025 P2 Q40","order":2034},
{"id":"p2-036","paper":2,"topic":"Boiler water","kind":"problem","front":"A 20 TPH boiler uses 30% make-up water with TDS 500 ppm (condensate TDS negligible). Maximum permissible boiler water TDS is 3,000 ppm. An RO plant costing Rs 40 lakh will cut make-up TDS to 100 ppm. Blowdown water is at 180 °C and feed water at 60 °C. Boiler efficiency 82%, fuel oil GCV 10,200 kcal/kg, oil cost Rs 45,000/t, 8,000 h/yr. Find the reduction in blowdown and the simple payback.","back":"Blowdown falls from 5.26% to 1.01% (≈ 851 kg/h less); oil saved ≈ 98 t/yr worth ≈ Rs 43.9 lakh; payback ≈ 10.9 months","explain":"Feed water TDS is the make-up TDS diluted by the condensate. Blowdown % = feed TDS/(max TDS − feed TDS). The heat saved is the sensible heat of the blowdown water above feed temperature, converted to fuel via boiler efficiency and GCV. Better water treatment pays back quickly through lower blowdown.","steps":[{"prompt":"Find feed water TDS before and after.","answer":"Before: 0.30 × 500 = 150 ppm; after: 0.30 × 100 = 30 ppm","explain":"Feed TDS = make-up fraction × make-up TDS (condensate ≈ 0)."},{"prompt":"Calculate blowdown % in both cases.","answer":"Before: 150/(3000−150) = 5.26%; after: 30/(3000−30) = 1.01%","explain":"Blowdown % = feed TDS × 100 / (max TDS − feed TDS)."},{"prompt":"Find reduction in blowdown flow.","answer":"(5.26 − 1.01)% × 20,000 = 851 kg/h","explain":"Applied to steam generation rate."},{"prompt":"Heat and fuel saved.","answer":"Heat = 851 × 1 × (180 − 60) = 102,073 kcal/h; oil = 102,073/(0.82 × 10,200) = 12.2 kg/h","explain":"Fuel = heat / (η × GCV)."},{"prompt":"Annual saving and payback.","answer":"12.2 × 8,000 = 98 t/yr × Rs 45,000 = Rs 43.9 lakh; payback = 40/43.9 ≈ 0.91 yr (10.9 months)","explain":"Simple payback = investment / annual savings."}],"flash":false,"source":"Based on BEE 2025 P2 L2(a)","order":2035},
{"id":"p2-037","paper":2,"topic":"Steam","kind":"fact","front":"What are sensible heat and latent heat of steam?","back":"Sensible heat raises water to its boiling (saturation) temperature; latent heat changes saturated water into steam at constant temperature and pressure.","explain":"Total enthalpy of dry saturated steam = sensible heat + latent heat. Process heating uses mainly the latent heat released when steam condenses, which is why condensing steam is such an effective heating medium.","flash":false,"source":"BEE 2024 P2 Q42, L3","order":2036},
{"id":"p2-038","paper":2,"topic":"Steam","kind":"fact","front":"As steam pressure increases (say from 3 to 10 bar), what happens to latent heat, saturation temperature and specific volume?","back":"Latent heat decreases, saturation temperature and sensible heat increase, specific volume decreases; total enthalpy rises only slightly.","explain":"Higher-pressure steam is denser, so it can be distributed in smaller pipes, but each kg carries less latent heat. For process heating it is best to distribute at higher pressure and reduce pressure close to the point of use.","flash":false,"source":"BEE 2024 P2 Q50","order":2037},
{"id":"p2-039","paper":2,"topic":"Steam","kind":"fact","front":"Why is dry saturated steam preferred for process heating rather than wet or superheated steam?","back":"Dry saturated steam gives up its latent heat at constant temperature with a high condensing heat transfer coefficient.","explain":"Wet steam carries water droplets that hold no latent heat and add a water film to the heat transfer surface. Superheated steam must first cool down to saturation as a gas, where heat transfer coefficients are low and temperature control is poor.","flash":false,"source":"BEE 2025 P2 Q26; BEE 2024 P2 L5","order":2038},
{"id":"p2-040","paper":2,"topic":"Steam","kind":"fact","front":"What happens to the enthalpy of steam when it passes through a pressure reducing valve (PRV)?","back":"It remains (essentially) the same – throttling is an isenthalpic process.","explain":"Because enthalpy stays constant while latent heat at the lower pressure is larger, the steam becomes drier (or slightly superheated). A PRV does not 'save energy' by lowering enthalpy; savings come from drier steam, lower losses and better temperature control at the user.","flash":true,"source":"BEE 2025 P2 Q42, S7, L2(b)","order":2039},
{"id":"p2-041","paper":2,"topic":"Steam","kind":"fact","front":"What is flash steam and how is it formed?","back":"Steam formed when hot condensate at high pressure is released to a lower pressure; the excess sensible heat boils part of it.","explain":"Condensate at, say, 10 bar is near 180 °C; at 2 bar water can only exist up to about 133 °C, so the surplus sensible heat converts a fraction into steam. Flash steam cannot be produced from condensate already at atmospheric pressure.","flash":false,"source":"BEE 2024 P2 Q5; BEE 2025 P2 Q6","order":2040},
{"id":"p2-042","paper":2,"topic":"Steam","kind":"fact","front":"Give the formula for the percentage of flash steam.","back":"Flash steam % = (S₁ − S₂) / L₂ × 100, where S₁ = sensible heat at higher pressure, S₂ = sensible heat at lower pressure, L₂ = latent heat at lower pressure.","explain":"Example: S₁ = 165, S₂ = 120, L₂ = 526 kcal/kg gives (165 − 120)/526 = 8.6% flash steam. Flash vessels separate this low-pressure steam for reuse.","flash":false,"source":"BEE 2024 P2 Q46, S3","order":2041},
{"id":"p2-043","paper":2,"topic":"Steam","kind":"fact","front":"What is a thermocompressor in a steam system?","back":"A steam-jet ejector that uses high-pressure motive steam to recompress low-pressure (flash/vapour) steam to an intermediate usable pressure.","explain":"Thermocompressors upgrade waste low-pressure steam, e.g. from flash vessels or dryers, so it can be reused instead of being vented. They have no moving parts.","flash":false,"source":"BEE 2025 P2 Q43","order":2042},
{"id":"p2-044","paper":2,"topic":"Steam","kind":"fact","front":"How is water hammer in steam mains prevented?","back":"Lay the mains with a continuous downward slope in the direction of flow and provide adequate drain points (with traps) at regular intervals.","explain":"Water hammer occurs when condensate collects and is picked up by high-velocity steam as slugs. Good practice includes a falling gradient (often quoted as about 125 mm per 30 m), drain pockets at low points and before risers/valves, and proper start-up warming.","flash":false,"source":"BEE 2024 P2 Q31","order":2043},
{"id":"p2-045","paper":2,"topic":"Steam","kind":"fact","front":"What are the three main jobs of a steam trap?","back":"Discharge condensate as soon as it forms, not allow live steam to escape, and discharge air and other non-condensable gases.","explain":"A trap that holds back condensate waterlogs equipment; one that leaks steam wastes energy. Air is a strong insulator and must be vented for good heat transfer. Steam traps are therefore essential to maintain steam quality and heat transfer.","flash":false,"source":"BEE 2024 P2 Q1, Q17","order":2044},
{"id":"p2-046","paper":2,"topic":"Steam","kind":"fact","front":"Name the three main families of steam traps with an example of each.","back":"Mechanical (float, inverted bucket); Thermostatic (bimetallic, balanced pressure); Thermodynamic (disc).","explain":"Mechanical traps sense the density difference between steam and condensate; thermostatic traps sense temperature; thermodynamic traps use the velocity/pressure effects of flash steam on a disc. A float trap is a mechanical trap.","flash":true,"source":"BEE 2025 P2 Q27","order":2045},
{"id":"p2-047","paper":2,"topic":"Steam","kind":"fact","front":"Name the benefits of recovering condensate back to the boiler.","back":"Saves fuel (hot feed water), saves water and water treatment chemicals, and reduces blowdown (condensate is nearly pure).","explain":"Condensate is distilled water carrying significant sensible heat. Each 6 °C rise in feed water temperature saves about 1% fuel, and lower feed TDS reduces blowdown losses.","flash":false,"source":"BEE 2025 P2 Q41","order":2046},
{"id":"p2-048","paper":2,"topic":"Steam","kind":"problem","front":"2,000 kg/h of condensate at 8 bar(g) (sensible heat 175 kcal/kg) is currently drained. The plant proposes to flash it to 1 bar(g) (sensible heat 120 kcal/kg, latent heat 526 kcal/kg), use the flash steam in a low-pressure process, and return the remaining condensate to the boiler at 90 °C (make-up water is at 30 °C). Boiler efficiency 80%, fuel GCV 10,000 kcal/kg, 6,000 h/yr. Find the flash steam quantity and annual fuel saving.","back":"Flash steam ≈ 10.46% = 209 kg/h; heat recovered ≈ 217,452 kcal/h; fuel saved ≈ 163.1 t/yr","explain":"Flash % = (S₁ − S₂)/L₂. The flash steam's latent heat displaces live LP steam, and the remaining hot condensate returned to the feed tank replaces cold make-up water. Both are converted to fuel via boiler efficiency and GCV.","steps":[{"prompt":"Calculate % flash steam.","answer":"(175 − 120)/526 = 10.46%","explain":"Flash % = (S₁ − S₂)/L₂."},{"prompt":"Flash steam quantity.","answer":"2,000 × 0.1046 = 209 kg/h","explain":"Applied to condensate flow."},{"prompt":"Balance condensate returned.","answer":"2,000 − 209 = 1,791 kg/h","explain":"Mass balance across flash vessel."},{"prompt":"Total heat recovered.","answer":"209 × 526 + 1,791 × (90 − 30) = 217,452 kcal/h","explain":"Latent heat of flash steam + sensible heat of returned condensate above make-up temperature."},{"prompt":"Annual fuel saving.","answer":"217,452 × 6,000 / (0.80 × 10,000) / 1000 = 163.1 t/yr","explain":"Fuel = heat / (η × GCV)."}],"flash":false,"source":"Based on BEE 2024 P2 S3","order":2047},
{"id":"p2-049","paper":2,"topic":"Steam","kind":"problem","front":"Water (8,000 kg/h) is heated from 30 °C to 70 °C using steam at 10 kg/cm²(g) with dryness fraction 0.92 (h_f = 186.6, h_fg = 477.6 kcal/kg). It is proposed to fit a PRV and supply steam at 2 kg/cm²(g) (h_f = 134.1, h_fg = 516.9 kcal/kg). Assuming only latent heat is used in the heater, find the dryness after the PRV and the steam saving.","back":"Dryness after PRV ≈ 0.952; steam use falls from ≈ 728 to ≈ 651 kg/h, saving ≈ 78 kg/h","explain":"Throttling through a PRV keeps enthalpy constant. Because latent heat is higher at low pressure, the same enthalpy gives drier steam, and each kg delivers more latent heat. The process load stays the same, so less steam is needed.","steps":[{"prompt":"Enthalpy before the PRV.","answer":"h = 186.6 + 0.92 × 477.6 = 626.0 kcal/kg","explain":"h = h_f + x·h_fg."},{"prompt":"Dryness after the PRV.","answer":"626.0 = 134.1 + x × 516.9 → x = 0.952","explain":"Isenthalpic throttling: h before = h after."},{"prompt":"Process heat load.","answer":"8,000 × 1 × (70 − 30) = 320,000 kcal/h","explain":"m × Cp × ΔT."},{"prompt":"Steam required before and after.","answer":"Before: 320,000/(0.92 × 477.6) = 728 kg/h; after: 320,000/(0.952 × 516.9) = 651 kg/h","explain":"Steam = load / (x × h_fg)."},{"prompt":"Steam saving.","answer":"728 − 651 = 78 kg/h","explain":"Difference in steam demand."}],"flash":false,"source":"Based on BEE 2025 P2 S7","order":2048},
{"id":"p2-050","paper":2,"topic":"Furnaces","kind":"fact","front":"How is furnace efficiency calculated by the direct method?","back":"η = Heat in stock (m × Cp × ΔT) / Heat in fuel (fuel mass × GCV) × 100.","explain":"Example: 10 t/h of steel heated from 40 to 1100 °C (Cp 0.13) needs 1,378,000 kcal/h; with 230 kg/h oil at 10,000 kcal/kg (2,300,000 kcal/h) efficiency ≈ 60%. Reheating furnace efficiencies are generally low, so heat losses dominate.","flash":false,"source":"BEE 2024 P2 Q2, S5","order":2049},
{"id":"p2-051","paper":2,"topic":"Furnaces","kind":"fact","front":"List the main heat losses in an industrial heating furnace.","back":"Flue gas loss; loss from moisture/hydrogen in fuel; wall (surface) loss; radiation and gas leakage through openings; heat stored in the structure; cooling water loss; losses with conveyors/fixtures.","explain":"Blowdown loss is a boiler loss, not a furnace loss. Flue gas loss is typically the largest, so excess air control and air preheating are the first actions.","flash":false,"source":"BEE 2024 P2 Q39","order":2050},
{"id":"p2-052","paper":2,"topic":"Furnaces","kind":"fact","front":"How does excess air affect flue gas losses in a furnace?","back":"Flue gas losses increase with both higher excess air and higher flue gas exit temperature.","explain":"More air means more mass of gas heated to exhaust temperature. Furnaces should be run with the minimum excess air for complete combustion and at a slight positive pressure to stop cold air ingress through openings.","flash":false,"source":"BEE 2025 P2 Q16, Q44","order":2051},
{"id":"p2-053","paper":2,"topic":"Furnaces","kind":"fact","front":"What is the main benefit of preheating combustion air in a furnace?","back":"Fuel saving – the air brings back heat recovered from the flue gases, so less fuel must be burnt.","explain":"Air preheating via recuperators or regenerators is the major energy-saving measure for high-temperature furnaces, also improving flame temperature. The saving is roughly the heat added to the air divided by the fuel's calorific value.","flash":false,"source":"BEE 2024 P2 Q19; BEE 2025 P2 Q45","order":2052},
{"id":"p2-054","paper":2,"topic":"Furnaces","kind":"problem","front":"An oil-fired reheating furnace heats 6 t/h of steel billets from 30 °C to 1,200 °C (Cp of steel 0.12 kcal/kg°C). Oil consumption is 300 litres/h, specific gravity 0.92, GCV 10,200 kcal/kg. Find (a) furnace efficiency by the direct method and (b) the heat losses expressed as litres/h of oil.","back":"(a) η ≈ 29.9%; (b) losses ≈ 1,972,800 kcal/h ≈ 210 litres/h of oil","explain":"Direct efficiency = heat absorbed by the stock / heat in fuel. Everything not absorbed by the stock is lost through flue gas, walls, openings, cooling water and so on – here more than half of the oil. This shows why flue gas heat recovery and excess air control matter so much in furnaces.","steps":[{"prompt":"Heat input from fuel.","answer":"300 × 0.92 × 10,200 = 2,815,200 kcal/h","explain":"Litres × SG × GCV."},{"prompt":"Heat absorbed by stock.","answer":"6,000 × 0.12 × (1,200 − 30) = 842,400 kcal/h","explain":"m × Cp × ΔT."},{"prompt":"Direct efficiency.","answer":"842,400 / 2,815,200 = 29.9%","explain":"Output / input."},{"prompt":"Heat lost and equivalent oil.","answer":"2,815,200 − 842,400 = 1,972,800 kcal/h → 1,972,800/10,200/0.92 ≈ 210 L/h","explain":"Loss / GCV gives kg; divide by SG for litres."}],"flash":false,"source":"Based on BEE 2024 P2 Q2, S5","order":2053},
{"id":"p2-055","paper":2,"topic":"Furnaces","kind":"problem","front":"An oil-fired furnace uses 200 kg/h of oil (GCV 10,000 kcal/kg, theoretical air 14 kg/kg fuel) with 15% excess air. Combustion air currently enters at 35 °C. A recuperator is proposed to preheat the air to 350 °C using flue gas entering at 900 °C. Take Cp of air and flue gas as 0.24 kcal/kg°C. Find (a) % fuel saving, (b) new oil consumption, (c) flue gas temperature leaving the recuperator.","back":"(a) ≈ 12.17% saving; (b) ≈ 175.7 kg/h; (c) ≈ 603 °C","explain":"Heat carried back into the furnace by the preheated air directly displaces fuel heat, so % saving ≈ heat added to air per kg fuel / GCV. The flue gas exit temperature comes from an energy balance across the recuperator: heat lost by gas = heat gained by air (flue gas mass = air + fuel).","steps":[{"prompt":"Actual air and flue gas per kg fuel.","answer":"Air = 14 × 1.15 = 16.10 kg; flue gas = 16.10 + 1 = 17.10 kg per kg fuel","explain":"Actual air = theoretical × (1 + EA); flue gas ≈ air + fuel."},{"prompt":"Heat picked up by air per kg fuel.","answer":"16.10 × 0.24 × (350 − 35) = 1,217.2 kcal/kg fuel","explain":"m × Cp × ΔT."},{"prompt":"% fuel saving.","answer":"1,217.2 / 10,000 = 12.17%","explain":"Recovered heat / GCV."},{"prompt":"New fuel consumption.","answer":"200 × (1 − 0.1217) = 175.7 kg/h","explain":"Old × (1 − saving)."},{"prompt":"Flue gas exit temperature.","answer":"17.10 × (900 − T) = 16.10 × 315 → T ≈ 603 °C","explain":"Energy balance (Cp equal on both sides)."}],"flash":false,"source":"Based on BEE 2025 P2 S1","order":2054},
{"id":"p2-056","paper":2,"topic":"Furnaces","kind":"problem","front":"A reheating furnace burns 500 kg/h of furnace oil (GCV 10,200 kcal/kg; theoretical air 14 kg/kg). Flue gas leaves the recuperator at 450 °C with 9% O₂; ambient is 30 °C. Burner tuning will reduce O₂ to 4% at the same exit temperature. Taking Cp of flue gas 0.24 kcal/kg°C and flue gas mass = air + 1 kg per kg fuel, estimate the fuel saving per hour and per year (7,200 h/yr).","back":"Flue gas loss falls from ≈ 2,570 to ≈ 1,844 kcal/kg fuel; saving ≈ 7.12% ≈ 35.6 kg/h ≈ 256 t/yr","explain":"Reducing excess air shrinks the mass of flue gas carrying heat to the stack. Following the BEE method, the reduction in flue gas loss per kg of fuel divided by GCV gives the fractional fuel saving. Excess air from 9% O₂ is 75% but from 4% O₂ only about 23.5%.","steps":[{"prompt":"Excess air at 9% and 4% O₂.","answer":"9/(21−9) = 75.0%; 4/(21−4) = 23.5%","explain":"EA = O₂/(21 − O₂)."},{"prompt":"Actual air and flue gas per kg fuel.","answer":"Before: 14 × 1.750 = 24.50 → FG 25.50 kg; after: 14 × 1.235 = 17.29 → FG 18.29 kg","explain":"AAS = 14 × (1 + EA); FG = AAS + 1."},{"prompt":"Flue gas loss per kg fuel.","answer":"Before: 25.50 × 0.24 × 420 = 2,570; after: 18.29 × 0.24 × 420 = 1,844 kcal/kg fuel","explain":"m × Cp × (Tfg − Ta)."},{"prompt":"Fractional fuel saving.","answer":"(2,570 − 1,844)/10,200 = 7.12%","explain":"Loss reduction / GCV."},{"prompt":"Hourly and annual saving.","answer":"500 × 0.0712 = 35.6 kg/h; × 7,200 h = 256 t/yr","explain":"Apply to current consumption."}],"flash":false,"source":"Based on BEE 2025 P2 L6","order":2055},
{"id":"p2-057","paper":2,"topic":"Insulation","kind":"fact","front":"What is the economic thickness of insulation (ETI)?","back":"The thickness at which the total annual cost (insulation cost/depreciation + cost of heat lost) is minimum.","explain":"As thickness rises, the cost of heat lost falls while insulation cost rises. On the ETI chart the X-axis is insulation thickness, the Y-axis annual cost, and the combined-cost curve has a minimum that marks the ETI.","flash":true,"source":"BEE 2024 P2 Q35, S6; BEE 2025 P2 Q29","order":2056},
{"id":"p2-058","paper":2,"topic":"Insulation","kind":"fact","front":"What is the BEE simplified formula for heat loss from an insulated surface?","back":"S = [10 + (Ts − Ta)/20] × (Ts − Ta) kcal/h·m², where Ts is surface and Ta ambient temperature (°C).","explain":"Multiply S by the outer surface area (π × outer diameter × length for pipes). Remember that the outer diameter grows with insulation thickness, so the area increases as insulation is added.","flash":false,"source":"BEE 2024 P2 L1; BEE 2025 P2 S6","order":2057},
{"id":"p2-059","paper":2,"topic":"Insulation","kind":"fact","front":"Which property must a good insulating material have, and give a material used for cold (low-temperature) insulation?","back":"Low thermal conductivity; polyurethane foam is widely used for low-temperature/cold insulation.","explain":"Insulating materials reduce heat loss (or gain). Low-temperature materials include polyurethane, expanded polystyrene and cork; medium/high-temperature materials include mineral wool, calcium silicate and ceramic fibre.","flash":false,"source":"BEE 2025 P2 Q28, Q46","order":2058},
{"id":"p2-060","paper":2,"topic":"Insulation","kind":"fact","front":"What are the advantages of ceramic fibre in high-temperature furnaces?","back":"Low thermal conductivity, very low heat storage (low density), light weight, thermal shock resistance and quick heat-up/cool-down.","explain":"Ceramic fibre blankets/modules are used as hot-face linings or back-up insulation. Their low thermal mass is especially valuable in batch furnaces that cycle frequently.","flash":false,"source":"BEE 2024 P2 Q20","order":2059},
{"id":"p2-061","paper":2,"topic":"Insulation","kind":"problem","front":"A 200 m steam line of 80 mm outer diameter has 25 mm insulation with surface temperature 85 °C. Adding 40 mm more insulation (total 65 mm) is expected to bring the surface to 48 °C. Ambient is 30 °C. Using S = [10 + (Ts − Ta)/20] × (Ts − Ta) kcal/h·m², boiler efficiency 80%, fuel GCV 10,000 kcal/kg, fuel cost Rs 55,000/t, 8,000 h/yr and added insulation cost Rs 1,500/m, find the annual fuel saving and payback.","back":"Heat loss falls from ≈ 57,279 to ≈ 25,888 kcal/h; fuel saving ≈ 31.4 t/yr (≈ Rs 17.27 lakh); payback ≈ 2.1 months","explain":"The surface heat loss rate per m² falls steeply as surface temperature drops, but the outer surface area grows with insulation thickness – always recompute the diameter. Heat saved is converted to fuel via boiler efficiency and GCV.","steps":[{"prompt":"Heat loss per m² – existing and proposed.","answer":"Existing: [10 + 55/20] × 55 = 701.25; proposed: [10 + 18/20] × 18 = 196.20 kcal/h·m²","explain":"BEE surface heat loss formula."},{"prompt":"Surface areas.","answer":"Existing OD = 0.08 + 2×0.025 = 0.13 m → A = π × 0.13 × 200 = 81.7 m²; new OD = 0.21 m → A = 131.9 m²","explain":"A = π × D × L, D including insulation."},{"prompt":"Total heat loss and reduction.","answer":"701.25 × 81.7 = 57,279; 196.20 × 131.9 = 25,888; reduction = 31,391 kcal/h","explain":"S × A."},{"prompt":"Annual fuel and money saved.","answer":"31,391 × 8,000 / (0.80 × 10,000) /1000 = 31.4 t/yr × Rs 55,000 = Rs 17.27 lakh","explain":"Fuel = heat / (η × GCV)."},{"prompt":"Simple payback.","answer":"Cost = 1,500 × 200 = Rs 3.0 lakh; payback = 3.0/17.27 yr ≈ 2.1 months","explain":"Investment / annual saving."}],"flash":false,"source":"Based on BEE 2024 P2 L1; BEE 2025 P2 S6","order":2060},
{"id":"p2-062","paper":2,"topic":"Refractories","kind":"fact","front":"List the key properties required of a refractory.","back":"High melting point/refractoriness, adequate strength (cold crushing strength, refractoriness under load), resistance to thermal shock, chemical/slag resistance, suitable porosity and bulk density, appropriate thermal conductivity, low creep and volume stability.","explain":"A refractory must withstand high temperature without softening, so a low melting point is wrong. Selection balances strength against insulation value and the chemical environment (acidic, basic or neutral).","flash":false,"source":"BEE 2025 P2 Q47","order":2061}
]$cards$::jsonb);
